// Obtenemos el valor de 'respuesta_definitiva' desde el input
const respuestaDefinitiva = $('Webhook').first().json.body.custom_fields.respuesta_definitiva || '';

// Función para separar el texto y detectar múltiples tipos de enlaces (audio, imágenes, video, otros)
function separarMensaje(texto) {
  if (!texto) {
    return { texto: '', audio: [], imagenes: [], videos: [], links: [] };
  }

  // 1) Detectar TODAS las URLs (cualquier dominio)
  const urlRegex = /https?:\/\/[^\s,]+/g;
  const urls = texto.match(urlRegex) || [];

  // 2) Clasificar por extensión (ignorando querystrings)
  const audios = [];
  const imagenes = [];
  const videos = [];
  const otros = [];

  const isExt = (url, exts) => {
    const base = url.split('?')[0].toLowerCase();
    return new RegExp(`\\.(${exts.join('|')})$`, 'i').test(base);
  };

  for (const url of urls) {
    if (isExt(url, ['mp3','m4a','wav','ogg','aac','flac','webm'])) {
      audios.push(url);
    } else if (isExt(url, ['jpg','jpeg','png','gif','webp','bmp','svg'])) {
      imagenes.push(url);
    } else if (isExt(url, ['mp4','mov','mkv','avi','webm'])) {
      videos.push(url);
    } else {
      // Si querés, acá podés intentar heurísticas por path (ej. "/voice/" o "/image/")
      otros.push(url);
    }
  }

  // 3) Limpiar el texto (remover URLs y comas sobrantes, y compactar espacios)
  const textoLimpio = texto
    .replace(urlRegex, '')    // quitamos URLs
    .replace(/,/g, '')        // quitamos comas
    .replace(/\s{2,}/g, ' ')  // espacios múltiples -> uno
    .trim();

  return {
    texto: textoLimpio,
    audio: audios,       // compatibilidad con tu estructura actual
    imagenes,
    videos,
    links: otros
  };
}

// Llamamos a la función y devolvemos el resultado
return separarMensaje(respuestaDefinitiva);

